// ============================================================
// CLEAN AND EXPLODE SECTIONS v3.1
// v3.1 (19 Oct): review flags also catch evaluating or recommending phrases (strongest, suits,
// will find, natural place, within one Node). An empty writer answer stops the run with its own message.
// v3: every section is tidied before it reaches the page (dashes, stray markdown,
// "Access:" lines, people's email addresses), and style and fact checks are
// written to review_flags on each item. Flags never stop the run.
// EB-NODES pipeline. Place after "AI Node Writer".
// Language: JavaScript | Mode: Run Once for All Items
// ============================================================
//
// The agent returns all five sections in one JSON object. This node validates
// that object and emits one item per section, so each becomes its own row in
// Node_Body_Output and stays independently reviewable.
//
// BATCH SAFETY. Every item this node emits carries the name of the node it
// belongs to, taken from the current loop iteration rather than from the
// briefing node's full output. In batch mode the briefing node emits one item
// per Euro-BioImaging node, so $('Build node briefing').first() resolves to the
// FIRST node on every iteration, and all forty nodes' sections would be written
// to the sheet under one name. Downstream nodes read $json.node from here
// instead of reaching back.
//
// JSON extraction uses the balanced-brace scanner carried over from EB-TECH
// rather than a greedy regex. A greedy /\{[\s\S]*\}/ spans from the first "{"
// to the LAST "}", so if the model emits the object twice, or appends a fenced
// copy, both objects plus everything between them are swallowed into one invalid
// blob and a corrupted string reaches the sheet. The scanner returns the first
// span that actually parses and ignores anything after it.
// ============================================================

const EXPECTED_SECTIONS = [
  "Overview",
  "Imaging technologies offered",
  "Specialties and research focus",
  "Services and user support",
  "Facilities"
];

// ------------------------------------------------------------
// Extract the first complete, valid JSON object from a string.
// Walks the string tracking brace depth, respecting strings and escapes.
// ------------------------------------------------------------
function extractFirstJSONObject(text) {
  if (typeof text !== 'string') return null;

  for (let start = text.indexOf('{'); start !== -1; start = text.indexOf('{', start + 1)) {
    let depth = 0;
    let inString = false;
    let escaped = false;

    for (let i = start; i < text.length; i++) {
      const ch = text[i];
      if (escaped) { escaped = false; continue; }
      if (ch === '\\') { escaped = true; continue; }
      if (ch === '"') { inString = !inString; continue; }
      if (inString) continue;

      if (ch === '{') depth++;
      else if (ch === '}') {
        depth--;
        if (depth === 0) {
          try { return JSON.parse(text.slice(start, i + 1)); }
          catch (e) { break; }
        }
      }
    }
  }
  return null;
}

// ------------------------------------------------------------
// Normalise section titles for matching. The agent is told to return exact
// strings, but casing and stray whitespace should not cause a section to be
// dropped when the text itself is fine.
// ------------------------------------------------------------
function normTitle(v) {
  return String(v === undefined || v === null ? '' : v)
    .toLowerCase()
    .replace(/\s+/g, ' ')
    .trim();
}

// ------------------------------------------------------------
// One agent response per iteration. More than one means the loop is missing or
// misconfigured, which in batch mode would silently process only the first node.
// Fail loudly instead.
// ------------------------------------------------------------
const inputItems = $input.all();
if (inputItems.length !== 1) {
  throw new Error(`Expected exactly one agent response, received ${inputItems.length}. ` +
    'Check that "Loop Over Nodes" has a batch size of 1.');
}

// Identity of the node being processed on THIS iteration.
let currentNode = '';
let currentSubmissionId = null;
try {
  const loopItem = $('Read node file').first().json;
  currentNode = loopItem.node || '';
  currentSubmissionId = (loopItem.node_record && loopItem.node_record.submission_id) || null;
} catch (e) {
  throw new Error('Could not read from "Read node file".');
}
if (!currentNode) {
  throw new Error('The current loop item carries no node name.');
}

const raw = inputItems[0].json.output;
if (typeof raw === 'string' && !raw.trim()) {
  throw new Error('AI Node Writer returned an empty answer, most likely because thinking used all the tokens. ' +
    'Raise Maximum Number of Tokens in "Anthropic Chat Model" (21000 at most without streaming) and rerun this Node.');
}
// The writer is asked for {"sections": [...]}, but sometimes returns a bare list
// of sections, or the sections one after another. All three are accepted.
function allTopLevelObjects(text) {
  const out = [];
  let pos = 0;
  while (pos < text.length) {
    const start = text.indexOf('{', pos);
    if (start === -1) break;
    let depth = 0, inString = false, escaped = false, end = -1;
    for (let i = start; i < text.length; i++) {
      const ch = text[i];
      if (escaped) { escaped = false; continue; }
      if (ch === '\\') { escaped = true; continue; }
      if (ch === '"') { inString = !inString; continue; }
      if (inString) continue;
      if (ch === '{') depth++;
      else if (ch === '}') { depth--; if (depth === 0) { end = i; break; } }
    }
    if (end === -1) break;
    try { out.push(JSON.parse(text.slice(start, end + 1))); } catch (e) {}
    pos = end + 1;
  }
  return out;
}
function parseWriterOutput(value) {
  if (value && typeof value === 'object') return value;
  const text = String(value || '').replace(/^\s*```(?:json)?\s*/i, '').replace(/\s*```\s*$/, '').trim();
  try { return JSON.parse(text); } catch (e) {}
  const objs = allTopLevelObjects(text);
  const wrapped = objs.find(o => o && Array.isArray(o.sections));
  if (wrapped) return wrapped;
  const loose = objs.filter(o => o && o.section_title);
  if (loose.length) return { sections: loose };
  return objs[0] || null;
}
let parsed = parseWriterOutput(raw);
if (parsed && !Array.isArray(parsed) && !Array.isArray(parsed.sections) && parsed.section_title) {
  parsed = { sections: [parsed] };  // a single section; the missing-section check below reports the rest
}

if (!parsed) {
  throw new Error('AI Node Writer returned no parseable JSON object. Check the raw output field of that node.');
}

// ------------------------------------------------------------
// Accept either the documented shape {sections:[...]} or a bare array, since a
// model occasionally drops the wrapper. Anything else is a real failure.
// ------------------------------------------------------------
let sections = null;
if (Array.isArray(parsed.sections)) sections = parsed.sections;
else if (Array.isArray(parsed)) sections = parsed;

if (!sections) {
  throw new Error('Parsed JSON has no "sections" array. Got keys: ' + Object.keys(parsed).join(', '));
}

// ------------------------------------------------------------
// Match returned sections to the expected five, in the expected order.
// Missing sections throw rather than passing silently, because a page assembled
// from four sections looks finished and is not.
// ------------------------------------------------------------
const byTitle = {};
for (const s of sections) {
  if (!s || !s.section_title) continue;
  byTitle[normTitle(s.section_title)] = s;
}

const missing = EXPECTED_SECTIONS.filter(t => !byTitle[normTitle(t)]);
if (missing.length) {
  throw new Error('Agent output is missing section(s): ' + missing.join(' | ') +
    '. Returned: ' + sections.map(s => s && s.section_title).join(' | '));
}

// ------------------------------------------------------------
// TIDY. Dashes used as punctuation become commas; every other dash-like character
// becomes a plain hyphen, so "CSIC–UPV" and "CSIC-UPV" are the same text. Headings,
// bold markers, bullet marks and "Access:" lines do not belong in running text.
// ------------------------------------------------------------
function tidy(text) {
  return String(text)
    .replace(/\r\n?/g, '\n')
    .replace(/(\d)\s*[\u2013\u2014]\s*(\d)/g, '$1-$2')  // "3 – 4 days" is a range
    .replace(/[ \t]*\u2014[ \t]*/g, ', ')
    .replace(/ \u2013 /g, ', ')
    .replace(/[\u2010\u2011\u2012\u2013\u2212]/g, '-')
    .replace(/\*\*|__/g, '')
    .split('\n')
    .filter(line => !/^\s*#{1,6}\s/.test(line) && !/^\s*Access:/i.test(line))
    .map(line => line.replace(/^\s*[-*\u2022]\s+/, '').replace(/[ \t]+$/g, ''))
    .join('\n')
    .replace(/[^\S\n]{2,}/g, ' ')
    .replace(/ ,/g, ',')
    .replace(/,,+/g, ',')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

// ------------------------------------------------------------
// REVIEW FLAGS. Cheap checks for what Joakim looks for in review. They are stored
// on each item (and summed in "Render node page") but never stop the run.
// ------------------------------------------------------------
const WORD_RANGE = {
  "Overview": [230, 290], "Imaging technologies offered": [180, 240],
  "Specialties and research focus": [150, 200], "Services and user support": [140, 190], "Facilities": [180, 240]
};
const BANNED = /\b(state-of-the-art|cutting-edge|world-class|unique|comprehensive|diverse|robust|seamless(ly)?|wide range|notably|importantly|it is worth noting|most users|listed as|is listed|are listed|strongest|best suited|well suited|suits|natural place|will find|most support|within one node|in one place)\b/gi;
// Method names the writer could take from a facility description although the
// Node does not register them. Each is checked against the Node's technology labels.
const METHOD_CHECKS = [
  [/\bSTED\b/, /STED/], [/\b(STORM|dSTORM|PALM|single[- ]molecule locali[sz]ation|SMLM)\b/i, /SMLM|Single Molecule localization/i],
  [/\bMINFLUX\b/, /MINFLUX/], [/light[- ]sheet/i, /light[- ]?sheet|SPIM/i], [/two[- ]photon|multiphoton/i, /Two-photon|2P/i],
  [/\bFLIM\b|lifetime imaging/i, /FLIM|Lifetime/i], [/\bFRET\b/, /FRET/], [/\bFRAP\b/, /FRAP/],
  [/\bFCS\b|correlation spectroscopy/i, /FCS/], [/\bTIRF\b|total internal reflection/i, /TIRF/],
  [/spinning[- ]dis[ck]/i, /Spinning/i], [/structured illumination|\bSIM\b/, /\bSIM\b|Structured/i],
  [/expansion microscopy/i, /Expansion/i], [/\bRaman\b/i, /Raman/i], [/harmonic generation|\bSHG\b/i, /Harmonic/i],
  [/cryo[- ]electron tomography|\bcryo-ET\b/i, /Cryo Electron Tomography|Cryo-ET/i], [/\bFIB-SEM\b/i, /FIB/i],
  [/serial block[- ]face/i, /Serial Blockface|SBF/i], [/array tomography/i, /Array tomography/i],
  [/\bCLEM\b|correlative light and electron/i, /CLEM|Correlative/i], [/atomic force/i, /Atomic Force/i],
  [/intravital/i, /ntravital/i], [/\bSPECT\b/, /SPECT/], [/\bPET\b/, /PET/], [/\bMEG\b|magnetoencephalograph/i, /MEG/],
  [/optical coherence tomography|\bOCT\b/, /OCT/], [/photoacoustic/i, /hotoacoustic|PAI/i],
  [/mass spectrometry imaging|\bMALDI\b/i, /Mass spectrometry/i], [/micro-?CT\b/i, /CT/],
  [/high[- ]content screening/i, /high content|HTM/i], [/\bMRI\b|magnetic resonance/i, /MRI|MRS/i],
  [/\bultrasound\b/i, /\bUS\b|ultrasound/i], [/elemental analysis|\bEDX\b|\bEDS\b/i, /EDX|Elemental/i]
];
function reviewFlags(title, text, registeredLabels) {
  const flags = [];
  const words = text.split(/\s+/).filter(Boolean).length;
  let [lo, hi] = WORD_RANGE[title] || [0, 1e9];
  if (title === 'Facilities' && facilityCount === 1) [lo, hi] = [80, 160];  // one facility: four or five sentences
  if (words < lo * 0.9 || words > hi * 1.1) flags.push(`${words} words (aim ${lo} to ${hi})`);
  const semis = (text.match(/;/g) || []).length;
  const colons = (text.match(/:/g) || []).length;
  if (semis > 1) flags.push(`${semis} semicolons`);
  if (colons > 1) flags.push(`${colons} colons`);
  const banned = [...new Set((text.match(BANNED) || []).map(x => x.toLowerCase()))];
  if (banned.length) flags.push('wording: ' + banned.join(', '));
  if (/[\w.+-]+@[\w-]+(\.[\w-]+)+/.test(text)) flags.push('email address in text');
  const missing = METHOD_CHECKS.filter(([inText, inLabels]) => inText.test(text) && !registeredLabels.some(l => inLabels.test(l)))
    .map(([inText]) => (text.match(inText) || [''])[0]);
  if (missing.length) flags.push('methods not registered for this Node: ' + [...new Set(missing)].join(', '));
  return flags;
}
let registeredLabels = [];
let facilityCount = 0;
let hasServices = true;
try {
  const b = $('Read node file').first().json.node_briefing || {};
  hasServices = String(b.services_support || '').trim() !== '';
  facilityCount = (b.facilities || []).length;
  registeredLabels = (b.technologies_by_category || []).flatMap(g => (g.technologies || []).map(t => String(t.label || '')));
} catch (e) { /* the identity check below reports a missing node file */ }

const results = [];
for (const title of EXPECTED_SECTIONS) {
  const s = byTitle[normTitle(title)];
  const text = String(s.section_text || '').trim();

  // A Node with no services on record (no SLA and no service summary) gets no Services section.
  if (title === 'Services and user support' && !hasServices) {
    results.push({ json: { node: currentNode, submission_id: currentSubmissionId, section: title,
      section_text: '', word_count: 0, claimed_word_count: null, contained_em_dash: false, tidied: !!text,
      review_flags: text ? ['Services text dropped: no services on record'] : [],
      output: JSON.stringify({ section_title: title, section_text: '', word_count: 0 }) } });
    continue;
  }
  if (!text) {
    throw new Error(`Section "${title}" returned empty section_text.`);
  }

  // Recount rather than trusting the model's own word_count.
  const actualWords = text.split(/\s+/).filter(Boolean).length;

  // Dashes, stray markdown and "Access:" lines are removed here rather than by a rerun.
  const cleanText = tidy(text).replace(/\s*[\w.+-]+@[\w-]+(\.[\w-]+)+/g, '');
  const flags = reviewFlags(title, tidy(text), registeredLabels);

  results.push({
    json: {
      node: currentNode,
      submission_id: currentSubmissionId,
      section: title,
      section_text: cleanText,
      word_count: actualWords,
      claimed_word_count: s.word_count === undefined ? null : s.word_count,
      contained_em_dash: /\u2014/.test(text),
      tidied: cleanText !== text,
      review_flags: flags,
      // Stored to the sheet as the canonical record of this section.
      output: JSON.stringify({
        section_title: title,
        section_text: cleanText,
        word_count: actualWords
      })
    }
  });
}


// ------------------------------------------------------------
// IDENTITY CHECK. The text must be about the Node of this loop round: it has to
// name the Node or at least one of its facilities. Otherwise the run stops,
// so a page can never be filled with another Node's text.
// ------------------------------------------------------------
{
  const doc = $('Read node file').first().json;
  const b = doc.node_briefing || {};
  const names = new Set();
  const add = v => { const t = String(v || '').trim(); if (t.length >= 3) names.add(t.toLowerCase()); };
  add(doc.node);
  (String(doc.node).match(/\(([^)]+)\)/g) || []).forEach(m => add(m.slice(1, -1)));
  (b.facilities || []).forEach(f => { add(f.short_name); add(f.name); });
  const allText = results.map(r => r.json.section_text).join(' ').toLowerCase();
  const hit = [...names].some(n => allText.includes(n));
  if (!hit) {
    throw new Error(`The written text does not mention "${doc.node}" or any of its facilities. ` +
      'It may belong to another Node. Check that "AI Node Writer" has no pinned data and turn off prompt caching, then rerun this Node.');
  }
}

return results;

// ============================================================
// RENDER NODE PAGE v13 (Knowledge Base edition)
// v13 (19 Oct): the technology table has a "Confirmed facility providers" column (LNK-01 links
// only; "No confirmed facility provider yet" when none; "(qualified)" for a qualified allocation).
// Services that are not from a signed SLA are listed under "Services currently recorded (not in
// the signed SLA, please confirm)", without written text.
// v12: technology names in the table carry their technology URI (a link to their page
// once TECH_URL is set, the Access Portal has no technology pages yet); facility names
// in the facility table and locations carry their facility URI; no links in the text; NO_INSTRUMENT can fill empty instrument cells
// (off); a facility's general mailbox is listed before people.
// v11: a facility whose only link is the Node's Access Portal page gets no link;
// "+ network" is dropped from facility names; an address uses the first city of
// "Linz / Hagenberg / Wels / Steyr"; the service list drops bare "Instruments" and
// internal notes; a final pass removes dashes used as punctuation, unifies the
// other dash characters to a plain hyphen and drops any "Access:" line.
// v10: coordinates are no longer printed; contacts without a person show as
// "General enquiries".
// v9: the missing-information list is no longer printed on the page.
// v8: the facility table has three columns, Facility (linked), Institution and
// City; short names, types and URIs stay in the JSON. Paragraph breaks written
// by the AI are kept.
// v7: the technology table has two columns, Technology and Instrument
// highlights (every named model, grouped by facility short name).
// v6: the technology table lists every registered technology with the
// instruments that the providing facilities document for it.
// v5: section order Overview, Imaging technologies, Specialties, Services,
// Facilities; the technology list is a table with technology URIs and the
// facilities that provide each technology; the facility table opens the
// Facilities section; facility access routes are shown with the contacts.
// v4: reads the Node file from "Read node file" (one JSON per Node built from
// the EB Knowledge Base Master). Facility names link to their checked websites,
// the table carries the facility URI, the Services section is followed by the
// service list, each facility shows its address and coordinates, and a
// "Missing information" block lists what the master lacks for this Node.
// v3: batch safety, v2: short-name column (unchanged).
// Language: JavaScript | Mode: Run Once for All Items
// ============================================================
//
// Parts of the page that never touch the language model: the facility table,
// the technology list, the service list, the access and contact block and the
// missing-information block. They must appear exactly as recorded.
// ============================================================

let fileItem;
try {
  fileItem = $('Read node file').first().json;
} catch (e) {
  throw new Error('Could not read from "Read node file". That node must sit between the Drive download and "AI Node Writer".');
}

const briefing = fileItem.node_briefing;
const record = fileItem.node_record;
if (!briefing || !record) {
  throw new Error('The current Node file carries no node_briefing or node_record.');
}

const written = $('Clean and explode sections').all().map(i => i.json);
const foreign = written.filter(w => w.node && w.node !== fileItem.node);
if (foreign.length) {
  throw new Error(`Received ${foreign.length} section(s) belonging to a different node ` +
    `(expected "${fileItem.node}", saw "${foreign[0].node}"). The loop is not scoping correctly.`);
}
if (!written.length) {
  throw new Error('No written sections received from "Clean and explode sections".');
}

const SECTION_ORDER = [
  "Overview",
  "Imaging technologies offered",
  "Specialties and research focus",
  "Services and user support",
  "Facilities"
];

function s(v) {
  return (v === undefined || v === null) ? '' : String(v).trim();
}
function cell(v) {
  return s(v).replace(/\|/g, '\\|').replace(/\s*\n\s*/g, ' ');
}
function link(text, url, title) {
  if (!s(url)) return s(text);
  const t = s(title) ? ` "${s(title).replace(/"/g, '')}"` : '';
  return `[${s(text).replace(/[\[\]]/g, '')}](${s(url)}${t})`;
}
const PORTAL = s(briefing.identity && briefing.identity.access_portal_url);
// Technology pages. Leave empty until the Access Portal publishes one page per technology;
// then set it, for example 'https://www.eurobioimaging-access.eu/technology/{uri}', and every
// technology name in the table links to its page. The URI is always kept in the Node file.
const TECH_URL = '';
// Text for a technology row with no instrument on record. Left empty on the team's advice (16 Oct),
// so the page shows instruments only where we have them.
const NO_INSTRUMENT = '';
// A facility link that only leads to the Node's Access Portal page is not the facility's website.
function facilityLink(f) {
  const url = s(f.website);
  const usable = url && url !== PORTAL && !/eurobioimaging-access\.eu\/nodes\//i.test(url);
  // The facility URI rides along as the link title, so it is embedded but not printed.
  const uri = s(f.facility_uri);
  return link(facilityName(f), usable ? url : (uri ? `#${uri}` : ''), uri);
}
function facilityName(f) {
  return s(f.name).replace(/\s*\+\s*network$/i, '');
}

const sectionText = {};
for (const w of written) {
  if (w.section) sectionText[w.section] = s(w.section_text);
}

// ------------------------------------------------------------
// FACILITY LINKS IN THE TEXT: the first time a facility is named on the page (by its
// short name or full name), the name links to the facility's checked website.
// ------------------------------------------------------------
function linkFacilitiesInText(order) {
  const facs = (record.facilities || []).filter(f => f.status !== 'unconfirmed');
  const shortById = {};
  for (const bf of (briefing.facilities || [])) shortById[bf.facility_id] = s(bf.short_name);
  const targets = [];
  for (const f of facs) {
    const url = s(f.website);
    if (!url || url === PORTAL || /eurobioimaging-access\.eu\/nodes\//i.test(url)) continue;
    const names = [...new Set([s(f.name), shortById[f.facility_id] || s(f.short_name)].filter(n => n.length >= 3))];
    targets.push({ url, names: names.sort((a, b) => b.length - a.length), done: false });
  }
  const esc = t => t.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  for (const title of order) {
    let text = sectionText[title];
    if (!text) continue;
    // longest names first, so "LM facility" never links inside a longer name
    const all = targets.flatMap(t => t.names.map(n => ({ t, n }))).sort((a, b) => b.n.length - a.n.length);
    for (const { t, n } of all) {
      if (t.done) continue;
      const re = new RegExp(`(^|[^\\w\\[/-])(${esc(n)})(?![\\w-]|\\]\\()`);
      const m = text.match(re);
      if (!m) continue;
      const before = text.slice(0, m.index + m[1].length);
      if ((before.match(/\[/g) || []).length > (before.match(/\]/g) || []).length) continue;  // inside a link already
      text = before + `[${m[2]}](${t.url})` + text.slice(m.index + m[0].length);
      t.done = true;
    }
    sectionText[title] = text;
  }
}

const tableFacilities = (record.facilities || []).filter(f => f.status !== 'unconfirmed');

// ------------------------------------------------------------
// FACILITY TABLE: facility (linked to its website), institution, city
// ------------------------------------------------------------
function buildFacilityTable() {
  if (!tableFacilities.length) return '';
  let md = '| Facility | Institution | City |\n| --- | --- | --- |\n';
  for (const f of tableFacilities) {
    md += `| ${cell(facilityLink(f))} | ${cell(f.institution)} | ${cell(f.city)} |\n`;
  }
  return md + '\n';
}

// ------------------------------------------------------------
// TECHNOLOGY TABLE: every registered technology, its instruments and providers
// ------------------------------------------------------------
function buildTechnologyList() {
  const groups = briefing.technologies_by_category || [];
  if (!groups.length) return '';
  let md = '| Technology | Confirmed facility providers | Instrument highlights |\n| --- | --- | --- |\n';
  let anyQualified = false;
  for (const g of groups) {
    for (const t of g.technologies) {
      // Every technology name carries its URI: as a link to its page once TECH_URL is set,
      // until then as an in-page link "#<uri>" with the URI as its title.
      const uri = s(t.technology_uri);
      const name = !uri ? t.label
        : link(t.label, TECH_URL ? TECH_URL.replace('{uri}', uri) : `#${uri}`, uri);
      const label = name;  // the provisional flag stays in the Node file, not on the page (16 Oct)
      const inst = (t.instruments || []).join('; ') || NO_INSTRUMENT;
      const qual = new Set(t.provided_by_qualified || []);
      if (qual.size) anyQualified = true;
      const providers = (t.provided_by || []).map(p => qual.has(p) ? `${p} (qualified)` : p).join(', ')
        || 'No confirmed facility provider yet';
      md += `| ${cell(label)} | ${cell(providers)} | ${cell(inst)} |\n`;
    }
  }
  if (anyQualified) md += '\n(qualified): the provider link is recorded with a scope note and is to be confirmed by the Node.\n';
  return md + '\n';
}

// ------------------------------------------------------------
// SERVICE LIST from the Node's service summary
// ------------------------------------------------------------
function buildServiceList() {
  const list = (record.services_list || []).map(s)
    .filter(x => x && !/^instruments?$/i.test(x) && !/^\[.*\]$/.test(x) && !/INTERNAL/.test(x) && !/partial list/i.test(x));
  if (!list.length) return '';
  return list.map(x => `- ${x}`).join('\n') + '\n\n';
}

// ------------------------------------------------------------
// CONTACTS AND LOCATIONS
// ------------------------------------------------------------
function renderFacilityContact(f) {
  // A general mailbox (no person named) comes first, people after it.
  const qc = [...(f.contacts || [])].sort((a, b) => (s(a.full_name) ? 1 : 0) - (s(b.full_name) ? 1 : 0));
  return qc.map(c => {
    const name = s(c.full_name);
    const email = s(c.email);
    if (!name) return email ? `${s(c.role) || 'General enquiries'}: ${email}` : '';
    const role = s(c.role) ? ` (${s(c.role)})` : '';
    return `${name}${role}${email ? ', ' + email : ''}`;
  }).filter(Boolean).join('; ');
}

function buildContactBlock() {
  let md = '';
  const nodeContact = s(record.node_contact && record.node_contact.primary);
  if (nodeContact) md += `**Node contact:** ${nodeContact}\n\n`;
  const additional = (record.node_contact && record.node_contact.additional) || [];
  if (additional.length) md += `**Additional contacts:** ${additional.join('; ')}\n\n`;
  const site = s(briefing.identity.website);
  if (site) md += `**Node website:** ${link(site, site)}\n\n`;
  const portal = s(briefing.identity.access_portal_url);
  if (portal) md += `**Euro-BioImaging Access Portal:** ${link(portal, portal)}\n\n`;

  if (tableFacilities.length) {
    md += '### Facility locations and contacts\n\n';
    for (const f of tableFacilities) {
      md += `**${facilityLink(f)}**  \n`;
      const city = s(f.city).split(/\s+\/\s+/)[0];  // "Linz / Hagenberg / Wels / Steyr": the address is in Linz
      const addr = [s(f.street_address), [s(f.postal_code), city].filter(Boolean).join(' '), s(f.country)].filter(Boolean);
      if (addr.length) md += `${addr.join(', ')}  \n`;
      // Coordinates stay in the Node file (latitude, longitude) but are not printed.
      const contact = renderFacilityContact(f);
      if (contact) md += `Contact: ${contact}  \n`;
      // Access routes stay in the Node file but are not printed (the Access Portal link covers access).
      md += '\n';
    }
  }
  return md;
}

// ------------------------------------------------------------
// ASSEMBLE
// ------------------------------------------------------------
// Facility links stay out of the written text (Joakim, 16 Oct): they appear only in the
// facility table and the facility locations. linkFacilitiesInText() is kept but not called.

const nodeName = s(briefing.identity.name);
let markdown = `# ${nodeName}\n\n`;
const missingSections = [];

for (const title of SECTION_ORDER) {
  const text = sectionText[title];
  if (!text) {
    // Services not from a signed SLA have no written text, only the recorded list.
    const services = title === 'Services and user support' && record.services_basis === 'DATABASE' ? buildServiceList() : '';
    if (services) {
      markdown += `## ${title}\n\n### Services currently recorded (not in the signed SLA, please confirm)\n\n${services}`;
      continue;
    }
    missingSections.push(title); continue;
  }
  if (title === 'Facilities') {
    // The facility table opens the section; the written text follows it.
    const table = buildFacilityTable();
    markdown += `## ${title}\n\n` + (table ? `${table}` : '') + `${text}\n\n`;
    continue;
  }
  markdown += `## ${title}\n\n${text}\n\n`;
  if (title === 'Imaging technologies offered') {
    const techList = buildTechnologyList();
    if (techList) markdown += `### Technologies and instruments\n\n${techList}`;
  }
  if (title === 'Services and user support') {
    const services = buildServiceList();
    const head = record.services_basis === 'DATABASE'
      ? 'Services currently recorded (not in the signed SLA, please confirm)' : 'Services in the signed SLA';
    if (services) markdown += `### ${head}\n\n${services}`;
  }
}

markdown += `## Access and contact\n\n${buildContactBlock()}`;

// Final pass over the whole page. A dash used as punctuation becomes a comma, any other
// dash-like character becomes a plain hyphen (so "CSIC–UPV" and "CSIC-UPV" read the same),
// and no "Access:" line is printed, because access always goes through Euro-BioImaging.
markdown = markdown
  .replace(/(\d)\s*[\u2013\u2014]\s*(\d)/g, '$1-$2')
  .replace(/[ \t]*\u2014[ \t]*/g, ', ')
  .replace(/ \u2013 /g, ', ')
  .replace(/[\u2010\u2011\u2012\u2013\u2212]/g, '-')
  .split('\n').filter(line => !/^\s*Access:/.test(line)).join('\n');

// The missing-information list is for review only. It stays in the Node file
// (missing_info) and in review/missing_information.md; it is not printed on the page.
const missingInfo = fileItem.missing_info || [];

const fileName = (fileItem.node_uri || nodeName.replace(/[^a-zA-Z0-9]+/g, '_').replace(/^_|_$/g, '')) + '.md';

return [{
  json: {
    node: nodeName,
    fileName: fileName,
    markdown: markdown,
    word_count_total: markdown.split(/\s+/).filter(Boolean).length,
    sections_included: SECTION_ORDER.filter(t => sectionText[t]),
    sections_missing: missingSections,
    facilities_in_table: tableFacilities.length,
    facilities_excluded: (record.facilities || []).filter(f => f.status === 'unconfirmed').length,
    technology_categories: (briefing.technologies_by_category || []).length,
    missing_info_items: missingInfo.length,
    // Style and fact checks from "Clean and explode sections", per section. For review only.
    review_flags: written.filter(w => (w.review_flags || []).length).map(w => `${w.section}: ${w.review_flags.join('; ')}`)
  }
}];

// ============================================================
// CREATE MARKDOWN FILE v1
// EB-NODES pipeline. Place after "Render node page".
// Language: JavaScript | Mode: Run Once for All Items
// ============================================================
//
// Converts the assembled markdown string into a binary file that the Google
// Drive node can upload. The binary property is named "data", which is what the
// Drive node's "Input Data Field Name" must be set to.
// ============================================================

const item = $input.first().json;
const markdown = item.markdown;
const fileName = item.fileName;

if (!markdown) {
  throw new Error('No markdown found on the incoming item. Check that "Render node page" ran and produced a markdown field.');
}
if (!fileName) {
  throw new Error('No fileName found on the incoming item.');
}

return [{
  json: {
    node: item.node,
    fileName: fileName,
    word_count_total: item.word_count_total,
    sections_included: item.sections_included,
    sections_missing: item.sections_missing
  },
  binary: {
    data: await this.helpers.prepareBinaryData(
      Buffer.from('\uFEFF' + markdown, 'utf-8'),
      fileName,
      'text/markdown; charset=utf-8'
    )
  }
}];

// ============================================================
// PICK NODE FILES v2
// Keeps the Node files (*.json) from the Drive folder listing and, if
// NODE_FILTER is set, only the Nodes whose file name contains one of the
// comma-separated words. A file name that appears twice is used once.
// Examples: NODE_FILTER = "swedish"   or   "danish, flanders, embl"   or   "" for all Nodes.
// Language: JavaScript | Mode: Run Once for All Items
// ============================================================
const NODE_FILTER = "";

const words = NODE_FILTER.split(',').map(w => w.trim().toLowerCase()).filter(Boolean);
const seen = new Set();
const files = [];
for (const f of $input.all().map(i => i.json)) {
  const name = String(f.name || '');
  const low = name.toLowerCase();
  if (!low.endsWith('.json') || low === 'node_files_index.json') continue;
  if (words.length && !words.some(w => low.includes(w))) continue;
  if (seen.has(low)) continue;   // the same file uploaded twice
  seen.add(low);
  files.push({ id: f.id, name });
}
files.sort((a, b) => a.name.localeCompare(b.name));

if (!files.length) {
  throw new Error('No Node files found. Check the folder in "List node files" and NODE_FILTER (now: "' + NODE_FILTER + '").');
}
return files.map(f => ({ json: f }));

// ============================================================
// READ NODE FILE v1
// Parses the downloaded Node file (built by build_node_files.py from the EB
// Knowledge Base Master) into node, country, node_briefing, node_record and
// missing_info, the shape "AI Node Writer" and "Render node page" expect.
// Language: JavaScript | Mode: Run Once for All Items
// ============================================================
const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
let doc;
try {
  doc = JSON.parse(buffer.toString('utf-8'));
} catch (e) {
  throw new Error('The Node file is not valid JSON: ' + e.message);
}
for (const key of ['node', 'node_briefing', 'node_record']) {
  if (!doc[key]) throw new Error(`The Node file has no "${key}".`);
}
return [{ json: doc }];
